// ============================================================
// Reports view
// ============================================================
// Reports are generated by the backend from the persisted state (findings,
// costs, remediations, audit events) and can be downloaded as PDF, CSV or JSON.

import { download, get, post } from '../api.js';
import { canAnalyze, registerActions, rerender } from '../state.js';
import { badge, dateTime, empty, html, money, mount, raw, table, titleCase, toast } from '../utils.js';

export const view = { id: 'reports', title: ['Exports', 'Reports'], render };

const TYPES = [
  { id: 'security', title: 'Security Report', desc: 'Findings with evidence, severity, compliance posture, remediation and verification.' },
  { id: 'cost', title: 'Cost Optimization Report', desc: 'Run-rate, history, anomalies and recommendations with estimated versus verified savings.' },
  { id: 'full', title: 'Full Infrastructure Report', desc: 'Everything above plus inventory, drift summary and the recent audit trail.' },
  { id: 'verification', title: 'Remediation Verification Report', desc: 'Before/after evidence for each executed remediation, with resolved findings.' },
];
let selected = 'full';
let preview = null;

async function render(box) {
  let list;
  try { list = await get('/api/sim/reports'); } catch (e) {
    if (e.code === 'no_environment') { mount(box, html`<div class="card panel">${empty('No simulated environment', 'Generate one on the Simulator page.')}</div>`); return; }
    throw e;
  }
  mount(box, html`
    <p class="page-intro">Reports are snapshots of the real application state at the moment you generate them. They separate <b>estimated</b> savings (projections), <b>simulated</b> results (what-if) and <b>verified</b> savings (confirmed by re-analysis in the simulator), and list the simulation's assumptions and limitations.</p>
    <div class="grid-2" style="grid-template-columns:repeat(4,1fr)">
      ${TYPES.map((t) => html`<button class="card panel" style="text-align:left;cursor:pointer;${selected === t.id ? 'border-color:var(--primary);box-shadow:0 0 0 2px var(--primary-soft)' : ''}" data-action="rep-select" data-type="${t.id}" aria-pressed="${selected === t.id}">
        <h3 style="font-size:14px">${t.title}</h3><p class="panel-note" style="margin-top:6px">${t.desc}</p></button>`)}
    </div>
    <div class="row" style="margin:6px 0 18px"><button class="btn btn-primary" data-action="rep-generate" ${raw(canAnalyze() ? '' : 'disabled title="Analyst or administrator role required"')}>Generate ${TYPES.find((t) => t.id === selected).title}</button></div>
    ${preview ? previewCard(preview) : ''}
    <div class="card panel"><div class="panel-head"><h3>Report history</h3></div>
      ${list.items.length ? table([
        { label: '#', render: (r) => r.id }, { label: 'Report', render: (r) => r.title, strong: true }, { label: 'Type', render: (r) => titleCase(r.report_type) },
        { label: 'Generated (UTC)', render: (r) => dateTime(r.created_at) }, { label: 'Sim time', render: (r) => dateTime(r.sim_time).slice(0, 10) }, { label: 'By', key: 'actor' },
        { label: 'Download', render: (r) => html`<div class="row">${['pdf', 'csv', 'json'].map((f) => html`<button class="btn btn-sm" data-action="rep-download" data-id="${r.id}" data-format="${f}">${f.toUpperCase()}</button>`)}<button class="btn btn-sm" data-action="rep-preview" data-id="${r.id}">View</button></div>` },
      ], list.items, { caption: 'Generated reports' }) : empty('No reports yet', 'Choose a report type and generate one.')}
    </div>`);
}

function previewCard(r) {
  const c = r.content;
  return html`<div class="card panel" style="margin-bottom:16px"><div class="panel-head"><h3>${c.title}</h3><span class="tag">report #${r.id} · generated ${dateTime(c.generated_at)} UTC · sim time ${dateTime(c.sim_time).slice(0, 10)}</span></div>
    <dl class="kv"><dt>Environment</dt><dd>${c.environment.name} · account ${c.environment.account_id} · ${c.environment.region} · seed ${c.environment.seed}</dd></dl>
    <div class="compare">
      ${c.security ? html`<div class="cell"><div class="k">Security score</div><div class="v">${c.security.score ?? '—'}</div><div class="s">${c.security.open_findings.length} open, ${c.security.resolved_findings.length} resolved</div></div>` : ''}
      ${c.cost ? html`<div class="cell"><div class="k">Run-rate (simulated)</div><div class="v">${money(c.cost.monthly_run_rate, 0)}</div><div class="s">last 30 days billed ${money(c.cost.last_30_days_total, 0)}</div></div>
        <div class="cell"><div class="k">Estimated savings</div><div class="v v-ok">${money(c.cost.estimated_monthly_savings, 0)}</div><div class="s"><span class="badge estimated">estimated</span></div></div>
        <div class="cell"><div class="k">Verified savings</div><div class="v">${money(c.cost.verified_monthly_savings, 0)}</div><div class="s"><span class="badge verified">verified (simulated)</span></div></div>` : ''}
      ${c.remediation ? html`<div class="cell"><div class="k">Remediations</div><div class="v">${c.remediation.length}</div><div class="s">${c.remediation.filter((x) => x.verification === 'VERIFIED').length} verified</div></div>` : ''}
    </div>
    ${c.remediation && c.remediation.length ? html`${table([{ label: 'ID', render: (m) => m.id }, { label: 'Target', render: (m) => `${m.target_kind} ${m.target_key}`, mono: true }, { label: 'Verification', render: (m) => badge(m.verification, m.verification === 'VERIFIED' ? 'verified' : 'not_resolved') },
      { label: 'Score', render: (m) => `${m.score_before} → ${m.score_after}` }, { label: 'Run-rate', render: (m) => `${money(m.cost_before, 0)} → ${money(m.cost_after, 0)}` }], c.remediation, { caption: 'Remediations in report' })}` : ''}
    <div class="section-title">Assumptions and limitations</div><ul style="margin-left:18px;font-size:12.5px;color:var(--text-dim)">${c.assumptions_and_limitations.map((l) => html`<li>${l}</li>`)}</ul>
    <div class="row" style="margin-top:12px">${['pdf', 'csv', 'json'].map((f) => html`<button class="btn btn-sm" data-action="rep-download" data-id="${r.id}" data-format="${f}">Download ${f.toUpperCase()}</button>`)}</div></div>`;
}

export function init() {
  registerActions({
    'rep-select': (el) => { selected = el.dataset.type; rerender(); },
    'rep-generate': async (el) => {
      el.disabled = true;
      try {
        const r = await post('/api/sim/reports', { report_type: selected });
        preview = await get('/api/sim/reports/' + r.id);
        toast(`${r.title} generated (#${r.id})`, 'success');
      } finally { el.disabled = false; }
      rerender();
    },
    'rep-preview': async (el) => { preview = await get('/api/sim/reports/' + el.dataset.id); rerender(); },
    'rep-download': async (el) => {
      const f = el.dataset.format;
      await download(`/api/sim/reports/${el.dataset.id}/download?format=${f}`, `cloudshield-report-${el.dataset.id}.${f}`);
      toast(`Downloaded report ${el.dataset.id} as ${f.toUpperCase()}`, 'success');
    },
  });
}
